{
  "fields": {
    "name": "ship-logs-security",
    "action_type": "SHELL",
    "code": "rsync -avz --include=\"*.log\" --include=\"*.log.gz\" --exclude=\"*\" \"{{input.source_dir}}/\" \"{{input.remote_user}}@{{input.remote_host}}:{{input.remote_dir}}/\" -e \"ssh -o StrictHostKeyChecking=no -p {{input.ssh_port}}\" && echo \"Logs shipped to {{input.remote_host}}:{{input.remote_dir}}\"",
    "expected_rc": 0,
    "schema": {
      "input": {
        "source_dir": {
          "type": "string",
          "description": "Local log directory"
        },
        "remote_host": {
          "type": "string",
          "description": "Remote log server hostname/IP"
        },
        "remote_dir": {
          "type": "string",
          "description": "Remote destination directory"
        },
        "remote_user": {
          "type": "string",
          "description": "SSH user for remote connection"
        },
        "ssh_port": {
          "type": "integer",
          "description": "SSH port number"
        }
      },
      "required": [
        "source_dir",
        "remote_host",
        "remote_dir",
        "remote_user",
        "ssh_port"
      ]
    }
  },
  "explanation": "Ships security log files to a remote server using rsync over SSH."
}

{
  "fields": {
    "name": "mail-csr-gen",
    "action_type": "SHELL",
    "code": "mkdir -p $(dirname {{input.key_path}}) && openssl genrsa -out {{input.key_path}} {{input.key_bits}} 2>&1 && chmod 600 {{input.key_path}} && openssl req -new -key {{input.key_path}} -out {{input.csr_path}} -subj \"/C={{input.country}}/ST={{input.state}}/L={{input.city}}/O={{input.organization}}/CN={{input.common_name}}\" 2>&1 && echo \"CSR generated:\" && openssl req -in {{input.csr_path}} -noout -subject -verify 2>&1 || (echo \"FAILED: CSR generation error\" >&2; exit 1)",
    "expected_rc": 0,
    "schema": {
      "input": {
        "common_name": {
          "type": "string",
          "description": "Common Name (CN) for the certificate"
        },
        "organization": {
          "type": "string",
          "description": "Organization name"
        },
        "country": {
          "type": "string",
          "description": "Two-letter country code (e.g. US, GB)"
        },
        "state": {
          "type": "string",
          "description": "State or province name"
        },
        "city": {
          "type": "string",
          "description": "City or locality name"
        },
        "key_path": {
          "type": "string",
          "description": "Output path for the private key"
        },
        "csr_path": {
          "type": "string",
          "description": "Output path for the CSR file"
        },
        "key_bits": {
          "type": "integer",
          "description": "RSA key size in bits (2048, 4096)"
        }
      },
      "required": [
        "common_name",
        "organization",
        "country",
        "state",
        "city",
        "key_path",
        "csr_path",
        "key_bits"
      ]
    }
  },
  "explanation": "Generates an RSA private key and Certificate Signing Request (CSR) for the mail service."
}

