{
  "fields": {
    "name": "Rotate API key for third-party",
    "action_type": "PYTHON",
    "code": "import secrets
import json
import os
import sys
from datetime import datetime, timezone

key_file = "{{input.key_file}}"
key_length = int("{{input.key_length}}" or "32")
backup = "{{input.backup}}" != "false"

old_key = ""
if os.path.isfile(key_file):
    with open(key_file, "r") as f:
        old_key = f.read().strip()
    if backup:
        ts = datetime.now(timezone.utc).strftime("%Y%m%d%H%M%S")
        backup_path = f"{{key_file}}.{{ts}}.bak"
        with open(backup_path, "w") as f:
            f.write(old_key)

new_key = secrets.token_urlsafe(key_length)
with open(key_file, "w") as f:
    f.write(new_key)
os.chmod(key_file, 0o600)

print(json.dumps({{
    "status": "rotated",
    "key_file": key_file,
    "old_key_prefix": old_key[:8] + "..." if old_key else "none",
    "new_key_prefix": new_key[:8] + "...",
}}))
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "key_file": {
          "type": "string",
          "description": "Path to the API key file"
        },
        "key_length": {
          "type": "string",
          "description": "New key length in bytes (default 32)"
        },
        "backup": {
          "type": "string",
          "description": "Backup old key: true/false (default true)"
        }
      },
      "required": [
        "key_file"
      ]
    }
  },
  "explanation": "Python action that rotates the third-party API key, backing up the old key and writing a new secure key to file."
}

