{
  "fields": {
    "name": "webapp-error-count",
    "action_type": "SHELL",
    "code": "if [ ! -f \"{{input.log_file}}\" ]; then echo \"FAILED: Log file not found: {{input.log_file}}\" >&2; exit 1; fi && ERROR_COUNT=$(grep -c -i \"{{input.error_pattern}}\" \"{{input.log_file}}\" 2>/dev/null || echo 0) && echo \"Error count in {{input.log_file}}: $ERROR_COUNT (pattern: {{input.error_pattern}})\" && if [ \"$ERROR_COUNT\" -ge \"{{input.threshold}}\" ]; then echo \"CRITICAL: $ERROR_COUNT errors found (threshold: {{input.threshold}})\" >&2; echo \"=== Recent matching lines ===\" && grep -i \"{{input.error_pattern}}\" \"{{input.log_file}}\" | tail -5; exit 1; else echo \"OK: Error count ($ERROR_COUNT) is below threshold ({{input.threshold}})\"; fi",
    "expected_rc": 0,
    "schema": {
      "input": {
        "log_file": {
          "type": "string",
          "description": "Path to the application log file"
        },
        "error_pattern": {
          "type": "string",
          "description": "Grep pattern to match errors (e.g. ERROR, FATAL, Exception)"
        },
        "threshold": {
          "type": "integer",
          "description": "Maximum acceptable error count"
        },
        "lookback_minutes": {
          "type": "integer",
          "description": "Number of minutes to look back in the log"
        }
      },
      "required": [
        "log_file",
        "error_pattern",
        "threshold",
        "lookback_minutes"
      ]
    }
  },
  "explanation": "Counts error occurrences in the webapp application log and alerts if the count exceeds the threshold."
}

{
  "fields": {
    "name": "test-runner-notify",
    "description": "Run test suite and send notification",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "git-pull",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "webhook_url": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch",
            "webhook_url"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "install-deps",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && pip install -r requirements.txt",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "run-tests",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && pytest --junitxml=/tmp/test-results.xml 2>&1 | tee /tmp/test-output.txt",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "notify-success",
        "action_type": "SHELL",
        "code": "PASS=$(grep -c \"passed\" /tmp/test-output.txt); curl -sf -X POST {{input.webhook_url}} -H \"Content-Type: application/json\" -d \"{\"text\":\"Tests passed: $PASS tests on {{input.branch}}\"}\"",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": true,
        "name": "notify-failure",
        "action_type": "SHELL",
        "code": "FAIL=$(tail -5 /tmp/test-output.txt); curl -sf -X POST {{input.webhook_url}} -H \"Content-Type: application/json\" -d \"{\"text\":\"Tests FAILED on {{input.branch}}: $FAIL\"}\"",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
