    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-pgbouncer",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y pgbouncer",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
