{
  "fields": {
    "name": "worker-error-count",
    "action_type": "SHELL",
    "code": "if [ ! -f \"{{input.log_file}}\" ]; then echo \"FAILED: Log file not found: {{input.log_file}}\" >&2; exit 1; fi && ERROR_COUNT=$(grep -c -i \"{{input.error_pattern}}\" \"{{input.log_file}}\" 2>/dev/null || echo 0) && echo \"Error count in {{input.log_file}}: $ERROR_COUNT (pattern: {{input.error_pattern}})\" && if [ \"$ERROR_COUNT\" -ge \"{{input.threshold}}\" ]; then echo \"CRITICAL: $ERROR_COUNT errors found (threshold: {{input.threshold}})\" >&2; echo \"=== Recent matching lines ===\" && grep -i \"{{input.error_pattern}}\" \"{{input.log_file}}\" | tail -5; exit 1; else echo \"OK: Error count ($ERROR_COUNT) is below threshold ({{input.threshold}})\"; fi",
    "expected_rc": 0,
    "schema": {
      "input": {
        "log_file": {
          "type": "string",
          "description": "Path to the application log file"
        },
        "error_pattern": {
          "type": "string",
          "description": "Grep pattern to match errors (e.g. ERROR, FATAL, Exception)"
        },
        "threshold": {
          "type": "integer",
          "description": "Maximum acceptable error count"
        },
        "lookback_minutes": {
          "type": "integer",
          "description": "Number of minutes to look back in the log"
        }
      },
      "required": [
        "log_file",
        "error_pattern",
        "threshold",
        "lookback_minutes"
      ]
    }
  },
  "explanation": "Counts error occurrences in the worker application log and alerts if the count exceeds the threshold."
}

{
  "fields": {
    "name": "dkim-signing",
    "description": "Set up OpenDKIM for email signing",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-opendkim",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y opendkim opendkim-tools",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-key-dir",
        "action_type": "SHELL",
        "code": "mkdir -p /etc/opendkim/keys/{{input.domain}} && chown -R opendkim:opendkim /etc/opendkim",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "domain": {
              "type": "string"
            },
            "selector": {
              "type": "string"
            }
          },
          "required": [
            "domain",
            "selector"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "generate-dkim-key",
        "action_type": "SHELL",
        "code": "opendkim-genkey -s {{input.selector}} -d {{input.domain}} -D /etc/opendkim/keys/{{input.domain}} && chown opendkim:opendkim /etc/opendkim/keys/{{input.domain}}/*",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "configure-opendkim",
        "action_type": "SHELL",
        "code": "cat > /etc/opendkim.conf <<DKIM\nSyslog yes\nDomain {{input.domain}}\nSelector {{input.selector}}\nKeyFile /etc/opendkim/keys/{{input.domain}}/{{input.selector}}.private\nSocket inet:8891@localhost\nCanonicalization relaxed/simple\nMode sv\nDKIM",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "integrate-postfix",
        "action_type": "SHELL",
        "code": "postconf -e \"milter_default_action = accept\" && postconf -e \"milter_protocol = 6\" && postconf -e \"smtpd_milters = inet:localhost:8891\" && postconf -e \"non_smtpd_milters = inet:localhost:8891\"",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "start-opendkim",
        "action_type": "SHELL",
        "code": "systemctl enable --now opendkim && systemctl restart postfix",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "show-dns-record",
        "action_type": "SHELL",
        "code": "cat /etc/opendkim/keys/{{input.domain}}/{{input.selector}}.txt",
        "target": "all",
        "parent_step_ids": [
          "6"
        ]
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-dkim",
        "action_type": "SHELL",
        "code": "systemctl stop opendkim; postconf -e \"smtpd_milters =\" && postconf -e \"non_smtpd_milters =\" && systemctl restart postfix; apt-get remove -y opendkim opendkim-tools",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "DKIM: install OpenDKIM, generate key, configure, integrate with Postfix, start, show DNS record."
}

