        "admin_user": {
          "type": "string",
          "description": "Admin user with CREATE DATABASE privilege"
        },
        "database": {
          "type": "string",
          "description": "Name of the database to create"
        },
        "owner": {
          "type": "string",
          "description": "Database owner role"
        },
        "encoding": {
          "type": "string",
          "description": "Character encoding (e.g. UTF8)"
        },
        "locale": {
          "type": "string",
          "description": "Locale for collation (e.g. en_US.UTF-8)"
        }
      },
      "required": [
        "host",
        "admin_user",
        "database",
        "owner",
        "encoding",
        "locale"
      ]
    }
  },
  "explanation": "Creates a new PostgreSQL database in the staging environment with specified owner and encoding."
}

