{
  "fields": {
    "name": "deploy-with-rollback",
    "description": "Deploy with automatic rollback on failure",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "snapshot-current",
        "action_type": "SHELL",
        "code": "TIMESTAMP=$(date +%%Y%%m%%d%%H%%M%%S) && cp -a {{input.app_dir}} /var/backups/app_$TIMESTAMP && echo $TIMESTAMP > /tmp/deploy_timestamp",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "svc_name": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch",
            "svc_name"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "git-pull",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "install-deps",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && npm ci",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "run-tests",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && npm test",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "restart-service",
        "action_type": "SHELL",
        "code": "systemctl restart {{input.svc_name}}",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "health-check",
        "action_type": "SHELL",
        "code": "sleep 5 && curl -sf http://localhost:3000/health",
        "target": "all",
        "parent_step_ids": [
          "5"
        ],
        "expected_rc": 0
      },
      {
        "id": "7",
        "undo": true,
        "name": "rollback-deploy",
        "action_type": "SHELL",
        "code": "TS=$(cat /tmp/deploy_timestamp) && rm -rf {{input.app_dir}} && cp -a /var/backups/app_$TS {{input.app_dir}} && systemctl restart {{input.svc_name}}",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
