          "type": "string",
          "description": "PostgreSQL host address"
        },
        "username": {
          "type": "string",
          "description": "Database user with vacuum privilege"
        },
        "database": {
          "type": "string",
          "description": "Database name"
        },
        "table_name": {
          "type": "string",
          "description": "Table to vacuum and analyze"
        }
      },
      "required": [
        "host",
        "username",
        "database",
        "table_name"
      ]
    }
