{
  "fields": {
    "name": "Rate-limited request to cloudflare",
    "action_type": "PYTHON",
    "code": "import json
import urllib.request
import urllib.error
import time
import sys

url = "{{input.url}}"
max_retries = int("{{input.max_retries}}" or "5")
api_key = "{{input.api_key}}"

for attempt in range(max_retries):
    req = urllib.request.Request(url, method="GET")
    req.add_header("Authorization", "Bearer " + api_key)
    try:
        resp = urllib.request.urlopen(req, timeout=30)
        data = json.loads(resp.read().decode())
        remaining = resp.headers.get("X-RateLimit-Remaining", "unknown")
        print(json.dumps({{"status": "ok", "attempt": attempt + 1, "rate_remaining": remaining, "data": data}}))
        sys.exit(0)
    except urllib.error.HTTPError as e:
        if e.code == 429:
            retry_after = int(e.headers.get("Retry-After", 2 ** attempt))
            print(f"Rate limited, retrying in {{retry_after}}s (attempt {{attempt + 1}}/{{max_retries}})")
            time.sleep(retry_after)
        else:
            print(json.dumps({{"status": "error", "code": e.code}}))
            sys.exit(1)

print(json.dumps({{"status": "exhausted", "message": "Max retries reached"}}))
sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "url": {
          "type": "string",
          "description": "API endpoint URL"
        },
        "api_key": {
          "type": "string",
          "description": "API key for auth"
        },
        "max_retries": {
          "type": "string",
          "description": "Max retries on rate limit (default 5)"
        }
      },
      "required": [
        "url",
        "api_key"
      ]
    }
  },
  "explanation": "Python action that calls cloudflare API with automatic retry on HTTP 429 rate limits using exponential backoff."
}

