        "keystore_path": {
          "type": "string",
          "description": "Path to the Java keystore (JKS) file"
        },
        "alias": {
          "type": "string",
          "description": "Alias name for the certificate in the keystore"
        },
        "store_password": {
          "type": "string",
          "description": "Keystore password"
        }
      },
      "required": [
        "cert_path",
        "keystore_path",
        "alias",
        "store_password"
      ]
    }
  },
