{
  "fields": {
    "name": "Remove user account",
    "action_type": "ANSIBLE",
    "code": "- name: Kill processes for {{input.username}}
  command: "pkill -u {{input.username}}"
  failed_when: false
  changed_when: false

- name: Remove user {{input.username}}
  user:
    name: "{{input.username}}"
    state: absent
    remove: yes
    force: yes

- name: Remove sudoers entry
  file:
    path: "/etc/sudoers.d/{{input.username}}"
    state: absent

- name: Verify user is removed
  command: "id {{input.username}}"
  register: id_check
  changed_when: false
  failed_when: id_check.rc == 0
",
    "schema": {
      "input": {
        "username": {
          "type": "string",
          "description": "Username to remove"
        }
      },
      "required": [
        "username"
      ]
    }
