        "action_type": "SHELL",
        "code": "cat > /etc/nginx/sites-available/proxy.conf <<CONF\n<VirtualHost *:80>\nServerName {{input.server_name}}\nProxyPass / http://{{input.backend_host}}:{{input.backend_port}}/\nProxyPassReverse / http://{{input.backend_host}}:{{input.backend_port}}/\n</VirtualHost>\nCONF",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "backend_host": {
              "type": "string"
            },
            "backend_port": {
              "type": "string"
            },
            "server_name": {
              "type": "string"
            }
          },
          "required": [
            "backend_host",
            "backend_port",
            "server_name"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "test-config",
        "action_type": "SHELL",
        "code": "nginx -t",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "expected_rc": 0
      },
      {
        "id": "4",
        "undo": false,
        "name": "reload-nginx",
        "action_type": "SHELL",
        "code": "systemctl reload nginx",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-proxy",
        "action_type": "SHELL",
        "code": "curl -sf -H \"Host: {{input.server_name}}\" http://localhost/",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-proxy",
        "action_type": "SHELL",
        "code": "rm -rf /etc/nginx && mv /etc/nginx.bak /etc/nginx && systemctl reload nginx",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Reverse proxy: backup, write proxy config, test, reload, verify with rollback."
}

{
  "fields": {
    "name": "deploy-mongodb",
    "description": "Deploy MongoDB with auth enabled",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "import-mongo-key",
        "action_type": "SHELL",
        "code": "curl -fsSL https://pgp.mongodb.com/server-7.0.asc | gpg --dearmor -o /usr/share/keyrings/mongodb-server-7.0.gpg",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "add-mongo-repo",
        "action_type": "SHELL",
        "code": "echo \"deb [signed-by=/usr/share/keyrings/mongodb-server-7.0.gpg] https://repo.mongodb.org/apt/ubuntu jammy/mongodb-org/7.0 multiverse\" > /etc/apt/sources.list.d/mongodb-org-7.0.list && apt-get update",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
