          "type": "string",
          "description": "Path to sshd_config file (default: /etc/ssh/sshd_config)"
        }
      },
      "required": [
        "sshd_config"
      ]
    }
  },
  "explanation": "Disables SSH root login on the bastion by setting PermitRootLogin no, with config validation and backup."
}

{
  "fields": {
    "name": "SQLite integrity check",
    "action_type": "PYTHON",
    "code": "import json
import sqlite3
import os
import sys

db_path = "{{input.db_path}}"

if not os.path.isfile(db_path):
    print(json.dumps({{"status": "error", "message": f"Database not found: {{db_path}}"}}))
    sys.exit(1)

try:
    conn = sqlite3.connect(db_path)
    cursor = conn.execute("PRAGMA integrity_check")
    results = cursor.fetchall()
    conn.close()
    ok = all(row[0] == "ok" for row in results)
    size_bytes = os.path.getsize(db_path)
    print(json.dumps({{
        "status": "ok" if ok else "corrupt",
        "db_path": db_path,
        "size_bytes": size_bytes,
        "integrity": [row[0] for row in results],
    }}))
    if not ok:
        sys.exit(1)
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "db_path": {
          "type": "string",
          "description": "Path to SQLite database file"
        }
      },
      "required": [
        "db_path"
      ]
    }
  },
  "explanation": "Python action that runs PRAGMA integrity_check on a metrics SQLite database and reports the result."
}

{
  "fields": {
    "name": "pg-replica-prep",
    "description": "Prepare PostgreSQL for streaming replication",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "backup-pg-conf",
        "action_type": "SHELL",
        "code": "cp /etc/postgresql/*/main/postgresql.conf /etc/postgresql/*/main/postgresql.conf.repl.bak && cp /etc/postgresql/*/main/pg_hba.conf /etc/postgresql/*/main/pg_hba.conf.repl.bak",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "set-wal-level",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*wal_level.*/wal_level = replica/\" /etc/postgresql/*/main/postgresql.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "set-max-wal-senders",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*max_wal_senders.*/max_wal_senders = 5/\" /etc/postgresql/*/main/postgresql.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "create-repl-user",
        "action_type": "SHELL",
        "code": "sudo -u postgres psql -c \"CREATE USER {{input.repl_user}} WITH REPLICATION PASSWORD '{{input.repl_pass}}'\"",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "repl_user": {
              "type": "string"
            },
            "repl_pass": {
              "type": "string"
            },
            "replica_ip": {
              "type": "string"
            }
          },
          "required": [
            "repl_user",
            "repl_pass",
            "replica_ip"
          ]
        }
      },
      {
        "id": "5",
        "undo": false,
        "name": "add-hba-entry",
        "action_type": "SHELL",
        "code": "echo \"host replication {{input.repl_user}} {{input.replica_ip}}/32 md5\" >> /etc/postgresql/*/main/pg_hba.conf",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "restart-postgresql",
        "action_type": "SHELL",
        "code": "systemctl restart postgresql",
        "target": "all",
        "parent_step_ids": [
          "2",
          "3",
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "verify-wal-level",
        "action_type": "SHELL",
        "code": "sudo -u postgres psql -c \"SHOW wal_level\" | grep replica",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
