{
  "fields": {
    "name": "Test network latency to cache",
    "action_type": "PYTHON",
    "code": "import json
import socket
import time
import sys

host = "{{input.host}}"
port = int("{{input.port}}")
count = int("{{input.count}}" or "5")
threshold_ms = float("{{input.threshold_ms}}" or "100")

latencies = []
failures = 0

for i in range(count):
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(5)
        start = time.time()
        sock.connect((host, port))
        elapsed_ms = (time.time() - start) * 1000
        sock.close()
        latencies.append(round(elapsed_ms, 2))
    except Exception:
        failures += 1

if not latencies:
    print(json.dumps({{"status": "error", "message": "All connection attempts failed"}}))
    sys.exit(1)

avg = round(sum(latencies) / len(latencies), 2)
result = {{
    "status": "ok" if avg <= threshold_ms else "warning",
    "host": host,
    "port": port,
    "avg_ms": avg,
    "min_ms": min(latencies),
    "max_ms": max(latencies),
    "samples": len(latencies),
    "failures": failures,
    "threshold_ms": threshold_ms,
}}
print(json.dumps(result))
if avg > threshold_ms:
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "host": {
          "type": "string",
          "description": "Target hostname or IP"
        },
        "port": {
          "type": "string",
          "description": "Target TCP port"
        },
        "count": {
          "type": "string",
          "description": "Number of connection attempts (default 5)"
        },
        "threshold_ms": {
          "type": "string",
          "description": "Max acceptable avg latency in ms (default 100)"
        }
      },
      "required": [
        "host",
        "port"
      ]
    }
  },
  "explanation": "Python action that measures TCP connection latency to a cache endpoint over multiple samples and alerts on high latency."
}

