{
  "fields": {
    "name": "uptime-monitor-setup",
    "description": "Set up endpoint uptime monitoring",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-check-script",
        "action_type": "SHELL",
        "code": "cat > /usr/local/bin/uptime-check.sh <<SCRIPT\n#!/bin/bash\nLOGFILE=/var/log/uptime-monitor.log\nfor URL in {{input.urls}}; do\n  STATUS=$(curl -sf -o /dev/null -w \"%%{http_code}\" --max-time 10 \"$URL\" 2>/dev/null)\n  echo \"$(date -Iseconds) $URL $STATUS\" >> $LOGFILE\n  if [ \"$STATUS\" != \"200\" ]; then\n    echo \"ALERT: $URL returned $STATUS\" | logger -t uptime-monitor\n  fi\ndone\nSCRIPT\nchmod +x /usr/local/bin/uptime-check.sh",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "urls": {
              "type": "string"
            },
            "interval_min": {
              "type": "string"
            }
          },
          "required": [
            "urls",
            "interval_min"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-log-file",
        "action_type": "SHELL",
        "code": "touch /var/log/uptime-monitor.log",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "3",
        "undo": false,
        "name": "add-cron-job",
        "action_type": "SHELL",
        "code": "(crontab -l 2>/dev/null; echo \"*/{{input.interval_min}} * * * * /usr/local/bin/uptime-check.sh\") | crontab -",
        "target": "all",
        "parent_step_ids": [
          "1",
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "run-initial-check",
        "action_type": "SHELL",
        "code": "/usr/local/bin/uptime-check.sh",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-log-output",
        "action_type": "SHELL",
        "code": "test -s /var/log/uptime-monitor.log",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-uptime-monitor",
        "action_type": "SHELL",
        "code": "crontab -l | grep -v uptime-check | crontab - && rm -f /usr/local/bin/uptime-check.sh /var/log/uptime-monitor.log",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "Uptime monitor: create check script, add cron job, run initial check, verify log."
}

{
  "fields": {
    "name": "auto-security-updates",
    "description": "Enable automatic security updates",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-unattended",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y unattended-upgrades apt-listchanges",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "enable-auto-updates",
        "action_type": "SHELL",
        "code": "cat > /etc/apt/apt.conf.d/20auto-upgrades <<CONF\nAPT::Periodic::Update-Package-Lists \"1\";\nAPT::Periodic::Unattended-Upgrade \"1\";\nAPT::Periodic::AutocleanInterval \"7\";\nCONF",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "configure-security-only",
        "action_type": "SHELL",
        "code": "sed -i \"s|//.*\"\\${distro_id}:${distro_codename}-security\"|\\t\"${distro_id}:${distro_codename}-security\"|\" /etc/apt/apt.conf.d/50unattended-upgrades",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "enable-email-notify",
        "action_type": "SHELL",
        "code": "sed -i \"s|//Unattended-Upgrade::Mail \"\"|Unattended-Upgrade::Mail \"{{input.admin_email}}\"|\" /etc/apt/apt.conf.d/50unattended-upgrades",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "schema": {
          "input": {
            "admin_email": {
              "type": "string"
            }
          },
          "required": [
            "admin_email"
          ]
        }
      },
      {
        "id": "5",
        "undo": false,
        "name": "dry-run-test",
        "action_type": "SHELL",
        "code": "unattended-upgrade --dry-run --debug",
        "target": "all",
        "parent_step_ids": [
          "3",
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-auto-updates",
        "action_type": "SHELL",
        "code": "rm -f /etc/apt/apt.conf.d/20auto-upgrades; apt-get remove -y unattended-upgrades",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Auto updates: install unattended-upgrades, enable periodic updates, security-only, email notify, dry-run test."
}

