{
  "fields": {
    "name": "Monitor redis container resources",
    "action_type": "PYTHON",
    "code": "import json
import subprocess
import sys

container = "{{input.container_name}}"
cpu_threshold = float("{{input.cpu_threshold}}" or "80")
mem_threshold = float("{{input.mem_threshold}}" or "80")

try:
    result = subprocess.run(
        ["docker", "stats", "--no-stream", "--format",
         "{{.CPUPerc}}|{{.MemPerc}}|{{.MemUsage}}|{{.NetIO}}|{{.BlockIO}}|{{.PIDs}}",
         container],
        capture_output=True, text=True, timeout=15
    )
    if result.returncode != 0:
        print(json.dumps({{"status": "error", "message": result.stderr.strip()}}))
        sys.exit(1)
    parts = result.stdout.strip().split("|")
    cpu_pct = float(parts[0].strip().rstrip("%"))
    mem_pct = float(parts[1].strip().rstrip("%"))
    status = "ok"
    if cpu_pct > cpu_threshold or mem_pct > mem_threshold:
        status = "warning"
    output = {{
        "status": status,
        "container": container,
        "cpu_percent": cpu_pct,
        "mem_percent": mem_pct,
        "mem_usage": parts[2].strip(),
        "net_io": parts[3].strip(),
        "block_io": parts[4].strip(),
        "pids": parts[5].strip(),
    }}
    print(json.dumps(output))
    if status == "warning":
        sys.exit(1)
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "container_name": {
          "type": "string",
          "description": "Docker container name to monitor"
        },
        "cpu_threshold": {
          "type": "string",
          "description": "CPU usage warning threshold percent (default 80)"
        },
        "mem_threshold": {
          "type": "string",
          "description": "Memory usage warning threshold percent (default 80)"
        }
      },
      "required": [
        "container_name"
      ]
    }
  },
  "explanation": "Python action that monitors redis Docker container CPU, memory, network, and block I/O usage with threshold alerting."
}

