{
  "fields": {
    "name": "HTTP PUT update zookeeper",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport sys\n\nurl = \"{{input.url}}\"\npayload = json.loads('{{input.payload}}')\ndata = json.dumps(payload).encode(\"utf-8\")\nreq = urllib.request.Request(url, data=data, method=\"PUT\")\nreq.add_header(\"Content-Type\", \"application/json\")\nreq.add_header(\"Authorization\", \"Bearer {{input.api_key}}\")\ntry:\n    resp = urllib.request.urlopen(req, timeout=30)\n    result = json.loads(resp.read().decode())\n    print(json.dumps({{\"status\": \"updated\", \"code\": resp.getcode(), \"result\": result}}))\nexcept urllib.error.HTTPError as e:\n    print(json.dumps({{\"status\": \"failed\", \"code\": e.code, \"error\": e.read().decode()}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "url": {
          "type": "string",
          "description": "Resource URL to update"
        },
        "payload": {
          "type": "string",
          "description": "JSON update payload"
        },
        "api_key": {
          "type": "string",
          "description": "API key for auth"
        }
      },
      "required": [
        "url",
        "payload",
        "api_key"
      ]
    }
  },
  "explanation": "Python action that sends an HTTP PUT request to update a resource in zookeeper with JSON payload and bearer auth."
}

