{
  "fields": {
    "name": "docker-volume-backup",
    "description": "Backup Docker volumes to compressed archive",
    "stop_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-backup-dir",
        "action_type": "SHELL",
        "code": "mkdir -p {{input.backup_dir}}",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "volume_name": {
              "type": "string"
            },
            "backup_dir": {
              "type": "string"
            }
          },
          "required": [
            "volume_name",
            "backup_dir"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "stop-using-containers",
        "action_type": "SHELL",
        "code": "CONTAINERS=$(docker ps -q --filter volume={{input.volume_name}}); if [ -n \"$CONTAINERS\" ]; then docker stop $CONTAINERS; echo \"$CONTAINERS\" > /tmp/vol_backup_containers; fi",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "backup-volume",
        "action_type": "SHELL",
        "code": "TIMESTAMP=$(date +%%Y%%m%%d%%H%%M%%S) && docker run --rm -v {{input.volume_name}}:/source -v {{input.backup_dir}}:/backup alpine tar czf /backup/{{input.volume_name}}_$TIMESTAMP.tar.gz -C /source .",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "restart-containers",
        "action_type": "SHELL",
        "code": "if [ -f /tmp/vol_backup_containers ]; then cat /tmp/vol_backup_containers | xargs docker start; rm /tmp/vol_backup_containers; fi",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-backup",
        "action_type": "SHELL",
        "code": "ls -lh {{input.backup_dir}}/{{input.volume_name}}_*.tar.gz | tail -1",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      }
    ]
  },
  "explanation": "Volume backup: mkdir, stop containers using volume, tar the volume, restart containers, verify archive."
}

{
  "fields": {
    "name": "uptime-monitor-setup",
    "description": "Set up endpoint uptime monitoring",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-check-script",
        "action_type": "SHELL",
        "code": "cat > /usr/local/bin/uptime-check.sh <<SCRIPT\n#!/bin/bash\nLOGFILE=/var/log/uptime-monitor.log\nfor URL in {{input.urls}}; do\n  STATUS=$(curl -sf -o /dev/null -w \"%%{http_code}\" --max-time 10 \"$URL\" 2>/dev/null)\n  echo \"$(date -Iseconds) $URL $STATUS\" >> $LOGFILE\n  if [ \"$STATUS\" != \"200\" ]; then\n    echo \"ALERT: $URL returned $STATUS\" | logger -t uptime-monitor\n  fi\ndone\nSCRIPT\nchmod +x /usr/local/bin/uptime-check.sh",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "urls": {
              "type": "string"
            },
            "interval_min": {
              "type": "string"
            }
          },
          "required": [
            "urls",
            "interval_min"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-log-file",
        "action_type": "SHELL",
        "code": "touch /var/log/uptime-monitor.log",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "3",
        "undo": false,
        "name": "add-cron-job",
        "action_type": "SHELL",
        "code": "(crontab -l 2>/dev/null; echo \"*/{{input.interval_min}} * * * * /usr/local/bin/uptime-check.sh\") | crontab -",
        "target": "all",
        "parent_step_ids": [
          "1",
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "run-initial-check",
        "action_type": "SHELL",
        "code": "/usr/local/bin/uptime-check.sh",
        "target": "all",
        "parent_step_ids": [
          "3"
        ]
      },
      {
        "id": "5",
        "undo": false,
        "name": "verify-log-output",
        "action_type": "SHELL",
        "code": "test -s /var/log/uptime-monitor.log",
        "target": "all",
        "parent_step_ids": [
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-uptime-monitor",
        "action_type": "SHELL",
        "code": "crontab -l | grep -v uptime-check | crontab - && rm -f /usr/local/bin/uptime-check.sh /var/log/uptime-monitor.log",
        "parent_step_ids": [
          "3"
        ]
      }
    ]
  },
  "explanation": "Uptime monitor: create check script, add cron job, run initial check, verify log."
}

