{
  "fields": {
    "name": "log-alerting",
    "description": "Set up log-based alerting",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-alert-script",
        "action_type": "SHELL",
        "code": "cat > /usr/local/bin/log-alert.sh <<SCRIPT\n#!/bin/bash\nPATTERN=\"{{input.alert_pattern}}\"\nLOGFILE=\"{{input.log_path}}\"\nERRORS=$(tail -100 \"$LOGFILE\" | grep -c \"$PATTERN\")\nif [ \"$ERRORS\" -gt {{input.threshold}} ]; then\n  echo \"ALERT: $ERRORS matches for $PATTERN in $LOGFILE\" | logger -t log-alert\nfi\nSCRIPT\nchmod +x /usr/local/bin/log-alert.sh",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "log_path": {
              "type": "string"
            },
            "alert_pattern": {
              "type": "string"
            },
            "threshold": {
              "type": "string"
            }
          },
          "required": [
            "log_path",
            "alert_pattern",
            "threshold"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "add-cron-alert",
        "action_type": "SHELL",
        "code": "(crontab -l 2>/dev/null; echo \"*/5 * * * * /usr/local/bin/log-alert.sh\") | crontab -",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "test-alert-script",
        "action_type": "SHELL",
        "code": "/usr/local/bin/log-alert.sh",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "expected_rc": 0
      },
      {
        "id": "4",
        "undo": true,
        "name": "undo-log-alerting",
        "action_type": "SHELL",
        "code": "crontab -l | grep -v log-alert | crontab - && rm -f /usr/local/bin/log-alert.sh",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Log alerting: create alert script, add cron, test. Matches pattern in log and fires syslog alert."
}

{
  "fields": {
    "name": "blue-green-single",
    "description": "Blue-green deployment on single server",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "detect-active-slot",
        "action_type": "SHELL",
        "code": "ACTIVE=$(readlink {{input.app_dir}}/current); if [ \"$ACTIVE\" = \"{{input.app_dir}}/blue\" ]; then echo green > /tmp/deploy_slot; else echo blue > /tmp/deploy_slot; fi",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "repo_url": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "repo_url",
            "branch"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "clone-to-inactive",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && rm -rf {{input.app_dir}}/$SLOT && git clone -b {{input.branch}} {{input.repo_url}} {{input.app_dir}}/$SLOT",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "install-deps-new",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && cd {{input.app_dir}}/$SLOT && npm ci",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "test-new-slot",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && cd {{input.app_dir}}/$SLOT && npm test",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "switch-symlink",
        "action_type": "SHELL",
        "code": "SLOT=$(cat /tmp/deploy_slot) && ln -sfn {{input.app_dir}}/$SLOT {{input.app_dir}}/current",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "restart-app",
        "action_type": "SHELL",
        "code": "systemctl restart app",
        "target": "all",
        "parent_step_ids": [
          "5"
        ]
      },
      {
        "id": "7",
        "undo": false,
        "name": "health-check",
        "action_type": "SHELL",
        "code": "sleep 3 && curl -sf http://localhost:3000/health",
        "target": "all",
        "parent_step_ids": [
          "6"
        ],
        "expected_rc": 0
      },
      {
        "id": "8",
        "undo": true,
        "name": "undo-blue-green",
        "action_type": "SHELL",
        "code": "ACTIVE=$(cat /tmp/deploy_slot); if [ \"$ACTIVE\" = \"green\" ]; then OTHER=blue; else OTHER=green; fi && ln -sfn {{input.app_dir}}/$OTHER {{input.app_dir}}/current && systemctl restart app",
        "parent_step_ids": [
          "5"
        ]
      }
    ]
  },
  "explanation": "Blue-green: detect active slot, clone to inactive, install, test, swap symlink, restart, health check."
}

{
