{
  "fields": {
    "name": "Trigger gcp-snapshot backup",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport sys\n\napi_url = \"{{input.api_url}}\"\napi_key = \"{{input.api_key}}\"\nresource_id = \"{{input.resource_id}}\"\nbackup_name = \"{{input.backup_name}}\" or \"auto-backup\"\n\npayload = {{\"resource_id\": resource_id, \"name\": backup_name}}\ndata = json.dumps(payload).encode(\"utf-8\")\nreq = urllib.request.Request(api_url, data=data, method=\"POST\")\nreq.add_header(\"Content-Type\", \"application/json\")\nreq.add_header(\"Authorization\", \"Bearer \" + api_key)\ntry:\n    resp = urllib.request.urlopen(req, timeout=60)\n    result = json.loads(resp.read().decode())\n    print(json.dumps({{\"status\": \"backup_initiated\", \"resource\": resource_id, \"backup\": backup_name}}))\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "api_url": {
          "type": "string",
          "description": "Backup API endpoint URL"
        },
        "api_key": {
          "type": "string",
          "description": "API key for auth"
        },
        "resource_id": {
          "type": "string",
          "description": "Resource ID to back up"
        },
        "backup_name": {
          "type": "string",
          "description": "Backup name label (optional)"
        }
      },
      "required": [
        "api_url",
        "api_key",
        "resource_id"
      ]
    }
  },
  "explanation": "Python action that triggers a cloud backup on gcp-snapshot for a specified resource via API."
}

