}

{
  "fields": {
    "name": "Base64 decode data",
    "action_type": "PYTHON",
    "code": "import base64
import json
import sys

operation = "{{input.operation}}" or "encode"
input_path = "{{input.input_path}}"
output_path = "{{input.output_path}}"

try:
    with open(input_path, "rb") as f:
        data = f.read()

    if operation == "encode":
        result = base64.b64encode(data)
    elif operation == "decode":
        result = base64.b64decode(data)
    else:
        print(json.dumps({{"status": "error", "message": f"Unknown operation: {{operation}}"}}))
        sys.exit(1)

    with open(output_path, "wb") as f:
        f.write(result)

    print(json.dumps({{
        "status": "ok",
        "operation": operation,
        "input_size": len(data),
        "output_size": len(result),
    }}))
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "operation": {
          "type": "string",
          "description": "Operation: encode or decode"
        },
        "input_path": {
          "type": "string",
          "description": "Path to input file"
        },
        "output_path": {
          "type": "string",
          "description": "Path for output file"
        }
      },
      "required": [
        "input_path",
        "output_path"
      ]
    }
  },
  "explanation": "Python action that performs base64 decode on file data and writes the result to an output file."
}

