{
  "fields": {
    "name": "Query systemd journal for docker",
    "action_type": "PYTHON",
    "code": "import json
import subprocess
import sys

unit = "{{input.unit}}"
since = "{{input.since}}" or "1 hour ago"
priority = "{{input.priority}}" or "err"
max_entries = int("{{input.max_entries}}" or "50")

try:
    cmd = [
        "journalctl", "-u", unit,
        "--since", since,
        "--priority", priority,
        "--no-pager", "-o", "json",
        "-n", str(max_entries),
    ]
    result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
    entries = []
    for line in result.stdout.strip().split("\n"):
        if line.strip():
            try:
                entries.append(json.loads(line))
            except json.JSONDecodeError:
                continue
    summary = {{
        "status": "ok",
        "unit": unit,
        "since": since,
        "priority": priority,
        "entry_count": len(entries),
        "messages": [e.get("MESSAGE", "") for e in entries[-20:]],
    }}
    print(json.dumps(summary))
except subprocess.TimeoutExpired:
    print(json.dumps({{"status": "error", "message": "journalctl timed out"}}))
    sys.exit(1)
except Exception as e:
    print(json.dumps({{"status": "error", "message": str(e)}}))
    sys.exit(1)
",
    "expected_rc": 0,
    "schema": {
      "input": {
        "unit": {
          "type": "string",
          "description": "Systemd unit name to query"
        },
        "since": {
          "type": "string",
          "description": "Time range (default "1 hour ago")"
        },
        "priority": {
          "type": "string",
          "description": "Minimum priority level (default "err")"
        },
        "max_entries": {
          "type": "string",
          "description": "Maximum entries to return (default 50)"
        }
      },
      "required": [
        "unit"
      ]
    }
  },
  "explanation": "Python action that queries the systemd journal for docker entries filtered by time range and priority level."
}

