{
  "fields": {
    "name": "Generate random session-token",
    "action_type": "PYTHON",
    "code": "import secrets
import json
import sys

length = int("{{input.length}}" or "32")
format_type = "{{input.format}}" or "hex"

if format_type == "hex":
    token = secrets.token_hex(length)
elif format_type == "urlsafe":
    token = secrets.token_urlsafe(length)
elif format_type == "bytes":
    import base64
    token = base64.b64encode(secrets.token_bytes(length)).decode()
else:
    token = secrets.token_hex(length)

print(json.dumps({{
    "status": "ok",
    "token": token,
    "format": format_type,
    "length": length,
}}))
",
