{
  "fields": {
    "name": "Create Opsgenie alert",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport sys\n\napi_key = \"{{input.api_key}}\"\nmessage = \"{{input.message}}\"\npriority = \"{{input.priority}}\" or \"P3\"\ndescription = \"{{input.description}}\"\nalias = \"{{input.alias}}\"\n\npayload = {{\n    \"message\": message,\n    \"priority\": priority,\n    \"description\": description,\n}}\nif alias:\n    payload[\"alias\"] = alias\n\ndata = json.dumps(payload).encode(\"utf-8\")\nurl = \"https://api.opsgenie.com/v2/alerts\"\nreq = urllib.request.Request(url, data=data, method=\"POST\")\nreq.add_header(\"Content-Type\", \"application/json\")\nreq.add_header(\"Authorization\", \"GenieKey \" + api_key)\ntry:\n    resp = urllib.request.urlopen(req, timeout=15)\n    result = json.loads(resp.read().decode())\n    print(json.dumps({{\"status\": \"created\", \"request_id\": result.get(\"requestId\")}}))\nexcept Exception as e:\n    print(json.dumps({{\"status\": \"error\", \"message\": str(e)}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "api_key": {
          "type": "string",
          "description": "Opsgenie API key"
        },
        "message": {
          "type": "string",
          "description": "Alert message"
        },
        "priority": {
          "type": "string",
          "description": "Priority: P1-P5 (default P3)"
        },
        "description": {
          "type": "string",
          "description": "Alert description"
        },
        "alias": {
          "type": "string",
          "description": "Alert alias for dedup (optional)"
        }
      },
      "required": [
        "api_key",
        "message"
      ]
    }
  },
  "explanation": "Python action that creates an Opsgenie alert with P5 priority using the Opsgenie REST API v2."
}

