{
  "fields": {
    "name": "SOAP request to erp",
    "action_type": "PYTHON",
    "code": "import json\nimport urllib.request\nimport sys\n\nurl = \"{{input.wsdl_url}}\"\nsoap_action = \"{{input.soap_action}}\"\nsoap_body = '{{input.soap_body}}'\n\nenvelope = (\n    '<?xml version=\"1.0\" encoding=\"UTF-8\"?>'\n    '<soap:Envelope xmlns:soap=\"http://schemas.xmlsoap.org/soap/envelope/\">'\n    '<soap:Body>' + soap_body + '</soap:Body>'\n    '</soap:Envelope>'\n)\n\nreq = urllib.request.Request(url, data=envelope.encode(\"utf-8\"), method=\"POST\")\nreq.add_header(\"Content-Type\", \"text/xml; charset=utf-8\")\nreq.add_header(\"SOAPAction\", soap_action)\ntry:\n    resp = urllib.request.urlopen(req, timeout=30)\n    body = resp.read().decode()\n    print(json.dumps({{\"status\": \"ok\", \"code\": resp.getcode(), \"response_length\": len(body)}}))\nexcept urllib.error.HTTPError as e:\n    print(json.dumps({{\"status\": \"error\", \"code\": e.code, \"message\": e.read().decode()[:500]}}))\n    sys.exit(1)\n",
    "expected_rc": 0,
    "schema": {
      "input": {
        "wsdl_url": {
          "type": "string",
          "description": "SOAP endpoint URL"
        },
        "soap_action": {
          "type": "string",
          "description": "SOAPAction header value"
        },
        "soap_body": {
          "type": "string",
          "description": "XML content for the SOAP body"
        }
      },
      "required": [
        "wsdl_url",
        "soap_action",
        "soap_body"
      ]
    }
  },
  "explanation": "Python action that sends a SOAP XML request to erp endpoint with proper envelope wrapping and SOAPAction header."
}

