{
  "fields": {
    "name": "artifact-cleanup",
    "description": "Clean up old CI/CD artifacts and images",
    "stop_on_error": false,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "clean-old-backups",
        "action_type": "SHELL",
        "code": "find /var/backups/app_* -maxdepth 0 -mtime +{{input.retention_days}} -exec rm -rf {} \\; 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "retention_days": {
              "type": "string"
            },
            "registry": {
              "type": "string"
            },
            "image_name": {
              "type": "string"
            }
          },
          "required": [
            "retention_days"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "clean-docker-images",
        "action_type": "SHELL",
        "code": "docker image prune -a --filter \"until={{input.retention_days}}d\" -f 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "3",
        "undo": false,
        "name": "clean-build-caches",
        "action_type": "SHELL",
        "code": "docker builder prune -f --keep-storage=5GB 2>/dev/null; npm cache clean --force 2>/dev/null; pip cache purge 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "4",
        "undo": false,
        "name": "clean-test-artifacts",
        "action_type": "SHELL",
        "code": "find /tmp -name \"test-results*.xml\" -mtime +7 -delete 2>/dev/null; find /tmp -name \"*_pre_ci.sql\" -mtime +3 -delete 2>/dev/null; true",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "5",
        "undo": false,
        "name": "report-disk-freed",
        "action_type": "SHELL",
        "code": "df -h / | tail -1",
        "target": "all",
        "parent_step_ids": [
          "1",
          "2",
          "3",
          "4"
        ]
      }
    ]
  },
  "explanation": "Artifact cleanup: parallel clean old backups, docker images, build caches, test artifacts, then report disk."
}

{
  "fields": {
    "name": "dovecot-imap",
    "description": "Install and configure Dovecot IMAP server",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-dovecot",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y dovecot-imapd dovecot-lmtpd",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "configure-maildir",
        "action_type": "SHELL",
        "code": "sed -i \"s|^#*mail_location.*|mail_location = maildir:~/Maildir|\" /etc/dovecot/conf.d/10-mail.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "configure-auth",
        "action_type": "SHELL",
        "code": "sed -i \"s/^#*disable_plaintext_auth.*/disable_plaintext_auth = yes/\" /etc/dovecot/conf.d/10-auth.conf && sed -i \"s/^#*auth_mechanisms.*/auth_mechanisms = plain login/\" /etc/dovecot/conf.d/10-auth.conf",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "configure-ssl",
        "action_type": "SHELL",
        "code": "sed -i \"s|^#*ssl_cert.*|ssl_cert = </etc/letsencrypt/live/{{input.domain}}/fullchain.pem|\" /etc/dovecot/conf.d/10-ssl.conf && sed -i \"s|^#*ssl_key.*|ssl_key = </etc/letsencrypt/live/{{input.domain}}/privkey.pem|\" /etc/dovecot/conf.d/10-ssl.conf && sed -i \"s/^#*ssl =.*/ssl = required/\" /etc/dovecot/conf.d/10-ssl.conf",
        "target": "all",
        "parent_step_ids": [
          "2",
          "3"
        ],
        "schema": {
          "input": {
            "domain": {
              "type": "string"
            }
          },
          "required": [
            "domain"
          ]
        }
      },
      {
        "id": "5",
        "undo": false,
        "name": "restart-dovecot",
        "action_type": "SHELL",
        "code": "systemctl enable --now dovecot",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "verify-imap",
        "action_type": "SHELL",
        "code": "echo \"A1 LOGOUT\" | openssl s_client -connect localhost:993 -quiet 2>/dev/null | grep -q \"OK\"",
        "target": "all",
        "parent_step_ids": [
          "5"
        ],
        "expected_rc": 0
      },
      {
        "id": "7",
        "undo": true,
        "name": "undo-dovecot",
        "action_type": "SHELL",
        "code": "systemctl stop dovecot; apt-get remove -y dovecot-imapd dovecot-lmtpd",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Dovecot: install, configure maildir+auth+SSL, restart, verify IMAP on port 993."
}

