{
  "fields": {
    "name": "private-registry",
    "description": "Deploy private Docker registry",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "create-registry-dirs",
        "action_type": "SHELL",
        "code": "mkdir -p /opt/registry/data /opt/registry/auth /opt/registry/certs",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "create-htpasswd",
        "action_type": "SHELL",
        "code": "docker run --rm --entrypoint htpasswd httpd:2 -Bbn {{input.reg_user}} {{input.reg_pass}} > /opt/registry/auth/htpasswd",
        "target": "all",
        "parent_step_ids": [
          "1"
        ],
        "schema": {
          "input": {
            "reg_user": {
              "type": "string"
            },
            "reg_pass": {
              "type": "string"
            },
            "reg_port": {
              "type": "string"
            }
          },
          "required": [
            "reg_user",
            "reg_pass",
            "reg_port"
          ]
        }
      },
      {
        "id": "3",
        "undo": false,
        "name": "start-registry",
        "action_type": "SHELL",
        "code": "docker run -d --name registry --restart unless-stopped -p {{input.reg_port}}:5000 -v /opt/registry/data:/var/lib/registry -v /opt/registry/auth:/auth -e REGISTRY_AUTH=htpasswd -e REGISTRY_AUTH_HTPASSWD_REALM=\"Registry Realm\" -e REGISTRY_AUTH_HTPASSWD_PATH=/auth/htpasswd registry:2",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "verify-registry",
        "action_type": "SHELL",
        "code": "sleep 3 && curl -sf -u {{input.reg_user}}:{{input.reg_pass}} http://localhost:{{input.reg_port}}/v2/_catalog",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "test-push-pull",
        "action_type": "SHELL",
        "code": "docker pull alpine:latest && docker tag alpine:latest localhost:{{input.reg_port}}/test-alpine && docker push localhost:{{input.reg_port}}/test-alpine && docker rmi localhost:{{input.reg_port}}/test-alpine",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-registry",
        "action_type": "SHELL",
        "code": "docker stop registry 2>/dev/null; docker rm registry 2>/dev/null; rm -rf /opt/registry",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Private registry: create dirs, generate htpasswd, start registry container, verify API, test push+pull."
}

{
  "fields": {
    "name": "auto-security-updates",
    "description": "Enable automatic security updates",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "install-unattended",
        "action_type": "SHELL",
        "code": "apt-get update && apt-get install -y unattended-upgrades apt-listchanges",
        "target": "all",
        "parent_step_ids": []
      },
      {
        "id": "2",
        "undo": false,
        "name": "enable-auto-updates",
        "action_type": "SHELL",
        "code": "cat > /etc/apt/apt.conf.d/20auto-upgrades <<CONF\nAPT::Periodic::Update-Package-Lists \"1\";\nAPT::Periodic::Unattended-Upgrade \"1\";\nAPT::Periodic::AutocleanInterval \"7\";\nCONF",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "configure-security-only",
        "action_type": "SHELL",
        "code": "sed -i \"s|//.*\"\\${distro_id}:${distro_codename}-security\"|\\t\"${distro_id}:${distro_codename}-security\"|\" /etc/apt/apt.conf.d/50unattended-upgrades",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "enable-email-notify",
        "action_type": "SHELL",
        "code": "sed -i \"s|//Unattended-Upgrade::Mail \"\"|Unattended-Upgrade::Mail \"{{input.admin_email}}\"|\" /etc/apt/apt.conf.d/50unattended-upgrades",
        "target": "all",
        "parent_step_ids": [
          "2"
        ],
        "schema": {
          "input": {
            "admin_email": {
              "type": "string"
            }
          },
          "required": [
            "admin_email"
          ]
        }
      },
      {
        "id": "5",
        "undo": false,
        "name": "dry-run-test",
        "action_type": "SHELL",
        "code": "unattended-upgrade --dry-run --debug",
        "target": "all",
        "parent_step_ids": [
          "3",
          "4"
        ],
        "expected_rc": 0
      },
      {
        "id": "6",
        "undo": true,
        "name": "undo-auto-updates",
        "action_type": "SHELL",
        "code": "rm -f /etc/apt/apt.conf.d/20auto-upgrades; apt-get remove -y unattended-upgrades",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Auto updates: install unattended-upgrades, enable periodic updates, security-only, email notify, dry-run test."
}

{
  "fields": {
    "name": "deploy-with-rollback",
    "description": "Deploy with automatic rollback on failure",
    "stop_on_error": true,
    "undo_on_error": true,
    "steps": [
      {
        "id": "1",
        "undo": false,
        "name": "snapshot-current",
        "action_type": "SHELL",
        "code": "TIMESTAMP=$(date +%%Y%%m%%d%%H%%M%%S) && cp -a {{input.app_dir}} /var/backups/app_$TIMESTAMP && echo $TIMESTAMP > /tmp/deploy_timestamp",
        "target": "all",
        "parent_step_ids": [],
        "schema": {
          "input": {
            "app_dir": {
              "type": "string"
            },
            "branch": {
              "type": "string"
            },
            "svc_name": {
              "type": "string"
            }
          },
          "required": [
            "app_dir",
            "branch",
            "svc_name"
          ]
        }
      },
      {
        "id": "2",
        "undo": false,
        "name": "git-pull",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && git pull origin {{input.branch}}",
        "target": "all",
        "parent_step_ids": [
          "1"
        ]
      },
      {
        "id": "3",
        "undo": false,
        "name": "install-deps",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && npm ci",
        "target": "all",
        "parent_step_ids": [
          "2"
        ]
      },
      {
        "id": "4",
        "undo": false,
        "name": "run-tests",
        "action_type": "SHELL",
        "code": "cd {{input.app_dir}} && npm test",
        "target": "all",
        "parent_step_ids": [
          "3"
        ],
        "expected_rc": 0
      },
      {
        "id": "5",
        "undo": false,
        "name": "restart-service",
        "action_type": "SHELL",
        "code": "systemctl restart {{input.svc_name}}",
        "target": "all",
        "parent_step_ids": [
          "4"
        ]
      },
      {
        "id": "6",
        "undo": false,
        "name": "health-check",
        "action_type": "SHELL",
        "code": "sleep 5 && curl -sf http://localhost:3000/health",
        "target": "all",
        "parent_step_ids": [
          "5"
        ],
        "expected_rc": 0
      },
      {
        "id": "7",
        "undo": true,
        "name": "rollback-deploy",
        "action_type": "SHELL",
        "code": "TS=$(cat /tmp/deploy_timestamp) && rm -rf {{input.app_dir}} && cp -a /var/backups/app_$TS {{input.app_dir}} && systemctl restart {{input.svc_name}}",
        "parent_step_ids": [
          "1"
        ]
      }
    ]
  },
  "explanation": "Rollback deploy: snapshot app dir, pull, install, test, restart, health check. Restores from snapshot on failure."
}

